// Checkout conversion fix: ensure paidEvents increment on successful payment
const { db } = require('../constants/db');

module.exports = async function handleCheckoutConversion(req, res) {
  try {
    const { sessionId, paymentStatus } = req.body;
    if (paymentStatus === 'completed') {
      // Increment paidEvents in revenue stats
      await db.collection('revenue_stats').updateOne(
        { _id: 'global' },
        { $inc: { paidEvents: 1 } }
      );
      // Log conversion
      console.log(`Checkout conversion: session ${sessionId} paid`);
      res.json({ success: true });
    } else {
      res.json({ success: false, reason: 'payment not completed' });
    }
  } catch (err) {
    console.error('Checkout conversion error:', err);
    res.status(500).json({ error: err.message });
  }
};
